function sumTo(n) {
  let total = 0
  for (let i = 1; i <= n; i++) total += i
  return total
}
function timesTable(n) {
  let text = ""
  for (let i = 1; i <= 10; i++) {
    text += (i > 1 ? ", " : "") + n * i
  }
  return text
}
function countVowels(word) {
  let count = 0
  for (const letter of word.toLowerCase()) {
    if ("aeiou".includes(letter)) count++
  }
  return count
}
function yearsToDouble(amount, rate) {
  let balance = amount
  let years = 0
  while (balance < amount * 2) {
    balance = balance * (1 + rate)
    years++
  }
  return years
}
